var min = 18;
var max = 30;
var r = Math.max(0, Math.min(1, (t - min) / (max - min)));
var red = Math.round(255 * r);
var blue = Math.round(255 * (1 - r));
return 'rgba(' + red + ',80,' + blue + ',0.62)';

